package com.ruoyi.paismart.application.intelligence;

import com.ruoyi.paismart.application.documents.DocumentService;
import com.ruoyi.paismart.application.jobs.JobService;
import com.ruoyi.paismart.infrastructure.Jsons;
import com.ruoyi.paismart.infrastructure.intelligence.IntelligenceSettings;
import java.sql.Connection;
import java.util.*;
import org.h2.jdbcx.JdbcDataSource;
import org.junit.jupiter.api.*;
import org.springframework.core.io.ClassPathResource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.jdbc.datasource.init.ScriptUtils;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** 固定标注样例独立复算；模型和检索仅为本地替身，报告/复核真实持久化。 */
class EvaluationBoundaryTest {
    @Test void originalSummaryKeepsSeparateRetrievalJudgeAndFailureDenominators() {
        var rows=List.of(caseRow(true,1.,1.,5,true,"OK",false,"RERANK"),caseRow(true,.5,.5,2,false,"PROMPT_OR_MODEL",true,"RERANK"),caseRow(false,0.,0.,1,false,"RETRIEVAL_MISS",false,"RRF"),caseRow(null,null,null,null,null,"JUDGE_FAILED",true,"TEXT_ONLY"));
        var summary=EvaluationAlgorithms.summarize(rows);
        assertEquals(4,summary.get("totalCases"));assertEquals(3,summary.get("labeledCases"));assertEquals(2,summary.get("retrievalHits"));assertEquals(.6667,summary.get("recallAtK"));assertEquals(.5,summary.get("mrr"));assertEquals(.5,summary.get("meanExpectedDocCoverage"));assertEquals(3,summary.get("judgedCases"));assertEquals(1,summary.get("correctCases"));assertEquals(2.6667,summary.get("meanJudgeScore"));assertEquals(.3333,summary.get("accuracy"));assertEquals(2,summary.get("needsHumanReviewCount"));assertEquals(1,summary.get("failedCases"));assertEquals(2L,((Map<?,?>)summary.get("retrievalModeCounts")).get("RERANK"));assertEquals(0L,((Map<?,?>)summary.get("diagnosisCounts")).get("MISS_BUT_CORRECT"));
    }
    @Test void unavailableMetricsRemainNullInsteadOfLookingLikeZeroQuality() {var summary=EvaluationAlgorithms.summarize(List.of(caseRow(null,null,null,null,null,"GENERATION_FAILED",false,"NONE")));for(String key:List.of("recallAtK","mrr","meanExpectedDocCoverage","meanJudgeScore","accuracy","ndcg"))assertNull(summary.get(key));assertEquals(1,summary.get("failedCases"));assertEquals(8,EvaluationAlgorithms.diagnosisGuide().size());}
    @Test void originalDiagnosisPrioritySeparatesModelMissAndUnlabeled() {var good=new EvaluationAlgorithms.Judge(5,true,"ok",null,false);var bad=new EvaluationAlgorithms.Judge(2,false,"bad",null,false);var broken=EvaluationAlgorithms.parseJudge("garbage");assertEquals("OK",EvaluationAlgorithms.diagnosis(true,true,good).name());assertEquals("PROMPT_OR_MODEL",EvaluationAlgorithms.diagnosis(true,true,bad).name());assertEquals("RETRIEVAL_MISS",EvaluationAlgorithms.diagnosis(false,false,null).name());assertEquals("MISS_BUT_CORRECT",EvaluationAlgorithms.diagnosis(false,true,good).name());assertEquals("GENERATION_FAILED",EvaluationAlgorithms.diagnosis(true,false,null).name());assertEquals("JUDGE_FAILED",EvaluationAlgorithms.diagnosis(true,true,broken).name());assertEquals("NOT_LABELED",EvaluationAlgorithms.diagnosis(null,true,bad).name());}
    @Test void judgeParserAcceptsWrapperButRejectsFractionalScoreAndTruthyStrings() {var judge=EvaluationAlgorithms.parseJudge("评判如下：\n{\"score\":\"4\",\"correct\":\"true\",\"reason\":\"有依据\"}\n完毕");assertFalse(judge.parseFailed());assertEquals(4,judge.score());assertEquals(true,judge.correct());assertTrue(EvaluationAlgorithms.parseJudge("{\"score\":1.5,\"correct\":true}").parseFailed());assertTrue(EvaluationAlgorithms.parseJudge("{\"score\":5,\"correct\":\"yes\"}").parseFailed());assertTrue(EvaluationAlgorithms.parseJudge("{}").parseFailed());}
    @Test void parserPreservesBomCommentsLineNumbersAndRequiredReferenceAnswer() {var rows=EvaluationAlgorithms.dataset("\uFEFF//注释\n#注释\n{\"question\":\"q\",\"referenceAnswer\":\"a\",\"expectedFileNames\":\"one.pdf\"}\n");assertEquals("line-3",rows.get(0).get("id"));assertEquals(List.of("one.pdf"),rows.get(0).get("expectedFileNames"));assertTrue(assertThrows(IllegalArgumentException.class,()->EvaluationAlgorithms.dataset("#第一行\n{\"question\":\"q\"}")).getMessage().contains("第2行"));assertThrows(IllegalArgumentException.class,()->EvaluationAlgorithms.dataset("{\"question\":\"q\",\"referenceAnswer\":\"a\",\"expectedFileNames\":[1]}"));}
    @Test void humanAgreementIndependentTenLabelFixtureIncludesScoresAndDisagreements() {boolean[] judge={true,true,true,true,true,true,false,false,false,false},human={true,true,true,true,false,false,false,false,false,true};List<Map<String,Object>> pairs=new ArrayList<>();for(int i=0;i<10;i++)pairs.add(Map.of("caseId","c"+i,"judge",judge[i],"human",human[i],"judgeScore",judge[i]?5:1,"humanScore",human[i]?4:1));var agreement=EvaluationAlgorithms.agreement(pairs,5,.8,null);assertEquals(7,agreement.get("agreedCases"));assertEquals(.7,(Double)agreement.get("agreementRate"),1e-9);assertEquals(.4,(Double)agreement.get("cohensKappa"),1e-9);assertEquals(1.5,agreement.get("meanAbsoluteScoreDiff"));assertEquals(List.of("c4","c5","c9"),agreement.get("disagreementCaseIds"));assertEquals("NEEDS_RECALIBRATION",agreement.get("status"));assertTrue(agreement.get("warning").toString().contains("70.0%"));}
    @Test void optionalKappaFloorCanRejectHighRawAgreement() {List<Map<String,Object>> pairs=new ArrayList<>();for(int i=0;i<10;i++)pairs.add(Map.of("caseId","c"+i,"judge",true,"human",i!=9));assertEquals("OK",EvaluationAlgorithms.agreement(pairs,5,.8,null).get("status"));assertEquals("NEEDS_RECALIBRATION",EvaluationAlgorithms.agreement(pairs,5,.8,.4).get("status"));assertNull(EvaluationAlgorithms.agreement(pairs,5,.8,null).get("meanAbsoluteScoreDiff"));}
    @Test void humanOnlyAndUncertainVerdictsDoNotBecomeComparable() {Map<String,Object> humanOnly=new LinkedHashMap<>();humanOnly.put("caseId","b");humanOnly.put("human",true);Map<String,Object> uncertain=new LinkedHashMap<>();uncertain.put("caseId","c");uncertain.put("judge",true);uncertain.put("human",null);var report=EvaluationAlgorithms.agreement(List.of(Map.of("caseId","a","judge",false,"human",true),humanOnly,uncertain),5,.8);assertEquals(3,report.get("reviewedCases"));assertEquals(1,report.get("humanOnlyCases"));assertEquals(1,report.get("comparableCases"));assertEquals("INSUFFICIENT_SAMPLE",report.get("status"));assertEquals("NO_REVIEWS",EvaluationAlgorithms.agreement(List.of(),5,.8).get("status"));}
    private static Map<String,Object> caseRow(Boolean hit,Double rr,Double coverage,Integer score,Boolean correct,String diagnosis,boolean review,String mode){Map<String,Object> row=new LinkedHashMap<>();row.put("retrievalHit",hit);row.put("reciprocalRank",rr);row.put("expectedDocCoverage",coverage);row.put("judgeScore",score);row.put("judgeCorrect",correct);row.put("diagnosis",diagnosis);row.put("needsHumanReview",review);row.put("retrievalMode",mode);return row;}

    JdbcTemplate db;GovernanceService governance;SearchService search;ModelGateway models;DocumentService docs;ProviderService providers;IntelligenceSettings settings;
    @BeforeEach void prepare() throws Exception {var source=new JdbcDataSource();source.setURL("jdbc:h2:mem:eval_"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1");try(Connection c=source.getConnection()){ScriptUtils.executeSqlScript(c,new ClassPathResource("db/paismart/V003__intelligence.sql"));ScriptUtils.executeSqlScript(c,new ClassPathResource("db/paismart/V005__evaluation_datasets.sql"));}db=new JdbcTemplate(source);var tx=new TransactionTemplate(new DataSourceTransactionManager(source));search=mock(SearchService.class);models=mock(ModelGateway.class);docs=mock(DocumentService.class);providers=mock(ProviderService.class);settings=mock(IntelligenceSettings.class);when(settings.text(anyString(),anyString())).thenAnswer(i->i.getArgument(1));when(settings.number(anyString(),anyInt())).thenAnswer(i->i.getArgument(1));when(providers.fromSnapshot(anyString())).thenReturn(mock(ProviderService.Provider.class));governance=new GovernanceService(db,tx,mock(JobService.class),search,mock(DocumentIntelligenceService.class),providers,docs,models,settings,mock(IndexCoordinator.class));}
    Map<String,Object> run(Map<String,Object> sample){return run(sample,Map.of());}
    Map<String,Object> run(Map<String,Object> sample,Map<String,Object> overrides) {Map<String,Object> config=new LinkedHashMap<>(Map.of("provider",Map.of(),"index",Map.of(),"topK",5,"humanSampleRate",0,"seed",42,"humanAgreement",Map.of("minComparableCases",5,"minAgreementRate",.8)));config.putAll(overrides);db.update("INSERT INTO ps_evaluation(id,user_id,label,state,job_id,config_json,dataset_json,created_at,updated_at) VALUES('eval',2,'固定样例','QUEUED','job',?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",Jsons.write(config),Jsons.write(List.of(sample)));governance.processJob(new JobService.Job("job",2,null,"EVALUATION_RUN","RUNNING",Map.of("evaluationId","eval"),Map.of(),"lease",null,0,null,1));return governance.report("eval");}
    @Test void storedGenerationAndJudgeTimeoutsRemainFrozenWhenDeploymentSettingsChange(){
        when(search.searchAt(any(),anyString(),anyInt(),anyString(),anyMap())).thenReturn(new SearchService.SearchResult(List.of(),"TEXT_ONLY",List.of(),0));when(search.expand(any(),anyList())).thenReturn(List.of());when(settings.number("eval.generation-timeout-seconds",90)).thenReturn(80);when(settings.number("eval.judge-timeout-seconds",60)).thenReturn(70);
        when(models.text(anyLong(),startsWith("eval-answer:"),anyString(),anyString(),anyInt(),any(),eq(23))).thenReturn("答案");when(models.text(anyLong(),startsWith("eval-judge:"),anyString(),anyString(),anyInt(),any(),eq(11))).thenReturn("{\"score\":5,\"correct\":true,\"reason\":\"依据正确\"}");
        var report=run(Map.of("id","case","question","问题","referenceAnswer","答案"),Map.of("generationTimeoutSeconds",23,"judgeTimeoutSeconds",11));assertEquals("COMPLETE",report.get("state"));assertEquals(23,((Map<?,?>)report.get("configuration")).get("generationTimeoutSeconds"));verify(models).text(eq(2L),startsWith("eval-answer:"),anyString(),anyString(),eq(1500),any(),eq(23));verify(models).text(eq(2L),startsWith("eval-judge:"),anyString(),anyString(),eq(300),any(),eq(11));
    }
    @Test void reportKeepsMissingExpectedFilenameInCoverageAndRawHitRanksBeforeExpansion() {var evidence=new SearchService.Evidence("chunk","doc",1,0,1,"one.pdf","原始证据","anchor","",.9,"TEXT_ONLY");var document=mock(DocumentService.Document.class);when(document.filename()).thenReturn("one.pdf");when(docs.getReadable(any(),eq("doc"))).thenReturn(document);when(search.searchAt(any(),anyString(),anyInt(),anyString(),anyMap())).thenReturn(new SearchService.SearchResult(List.of(evidence),"TEXT_ONLY",List.of("降级"),1));when(search.expand(any(),anyList())).thenReturn(List.of());when(models.text(anyLong(),startsWith("eval-answer:"),anyString(),anyString(),anyInt(),any(),eq(90))).thenReturn("答案");when(models.text(anyLong(),startsWith("eval-judge:"),anyString(),anyString(),anyInt(),any(),eq(60))).thenReturn("前言{\"score\":5,\"correct\":true,\"reason\":\"ok\"}尾声");var report=run(Map.of("id","case","question","问题","referenceAnswer","答案","expectedFileNames",List.of("one.pdf","missing.pdf")));Map<?,?> result=(Map<?,?>)((List<?>)report.get("cases")).get(0);assertEquals(.5,result.get("expectedDocCoverage"));assertEquals(true,result.get("retrievalHit"));assertEquals(1,result.get("firstRelevantRank"));assertEquals("OK",result.get("diagnosis"));assertNotNull(result.get("judgeRawOutput"));assertEquals(1.,((Map<?,?>)report.get("summary")).get("accuracy"));}
    @Test void retrievalAndJudgeFailuresRemainSeparateAndDurable() {when(search.searchAt(any(),anyString(),anyInt(),anyString(),anyMap())).thenThrow(new IllegalStateException("ES unavailable"));var report=run(Map.of("id","case","question","问题","referenceAnswer","答案","expectedDocumentIds",List.of("doc")));Map<?,?> result=(Map<?,?>)((List<?>)report.get("cases")).get(0);assertEquals("RETRIEVAL_FAILED",result.get("diagnosis"));assertEquals("COMPLETED_WITH_ERRORS",report.get("state"));assertNull(((Map<?,?>)report.get("summary")).get("recallAtK"));verifyNoInteractions(models);assertEquals(1L,db.queryForObject("SELECT COUNT(*) FROM ps_evaluation_case",Long.class));}
}
